      {
        "factor": "Franchise-driven 2026 release slate",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "A calendar packed with tentpoles increases the odds of at least one title crossing $1B worldwide."
      },
      {
        "factor": "Recent 1B box-office breakthroughs (2025)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Demonstrates durable capacity for 1B performances in the current market."
      },
      {
        "factor": "Global box office growth forecast for 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "A large global market provides scale for a 1B title to emerge."
      },
      {
        "factor": "Finite base rate of 1B films",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Historical rarity imposes a cap, tempering the probability despite strong slate."
      },
      {
        "factor": "International market growth driven by Hollywood product",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Growing demand abroad supports the potential for global milestones."
      },
      {
        "factor": "China market uncertainty could dampen upside",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Potential regional headwinds that could marginally reduce upside."
      }
    ],
    "synthesis_rationale": "Starting from a reasonable base-rate anchor, positive signals from franchise breadth, recent 1B breakthroughs, and global growth push the probability higher, while known limits on the number of 1B films and China risk pull it back. The final calibration yields a tightly bounded posterior around 0.98, with a 0.92–0.99 confidence range reflecting residual uncertainty and potential correlations among factors."
  }
}

